window.MG_LAZY_DATA["data/lazy/resources/hpc-v27-069-a53612baeb749921.json"]={sha256:"a53612baeb749921033f1e97de567b9fd6b1eb0dd64a3512abc68c29dbdf2890",value:{"sources":[{"id":"v27-case-d5b4bc970496056c","url":"https://mfem.org/integration/","title":"MFEM numerical integration","titleEn":"MFEM numerical integration","publisher":"MFEM / Lawrence Livermore National Laboratory","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"hpc-v27-069","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"hpc-v27-069","related":[{"id":"hpc-v27-070","referenceUrls":["https://dealii.org/9.6.0/doxygen/deal.II/step_6.html"],"title":"deal.II：懸掛節點的仿射約束與連續性","titleEn":"deal.II: hanging-node affine constraints and continuity","why":"用兩課的可觀察驗收條件比較模型邊界：驗收依完整被積函數；不能把此四次測例泛化為所有網格。","whyEn":"Compare model boundaries using observable acceptance criteria: Acceptance follows the complete integrand; this fourth-degree fixture does not certify every mesh.","difference":"使用原創合成資料研究「deal.II：懸掛節點的仿射約束與連續性」，從物理或資料契約推導計算，並以反例驗證。完成：交付邊座標圖、約束列、方向反例與組裝到回填的證據鏈。","differenceEn":"Investigate deal.II: hanging-node affine constraints and continuity using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver edge-coordinate diagrams, constraint rows, an orientation counterexample and evidence connecting assembly with solution reconstruction, explicitly limiting the interpolation rule to the chosen element.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["分別計兩個節點的四次方與權重，說明規則只保證至三次，因此失敗不是浮點微小誤差。","用權重 0.75、0.25 算基線，再用斜率四核算；保留端點、方向與位置。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Evaluate the fourth power at both nodes and apply their weights. Explain that the rule guarantees only degree-three exactness, so the observed discrepancy is a structural underintegration error rather than a tiny floating-point artifact.","Compute the baseline with weights 0.75 and 0.25 and independently check it using slope four. Preserve endpoints, orientation and position so the arithmetic can be reconstructed without the mesh software.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"hpc-v27-079","referenceUrls":["https://www.netlib.org/scalapack/slug/node75.html"],"title":"ScaLAPACK：區塊循環索引與矩陣所有權驗證","titleEn":"ScaLAPACK: block-cyclic indexing and matrix ownership","why":"用兩課的可觀察驗收條件比較模型邊界：驗收依完整被積函數；不能把此四次測例泛化為所有網格。","whyEn":"Compare model boundaries using observable acceptance criteria: Acceptance follows the complete integrand; this fourth-degree fixture does not certify every mesh.","difference":"使用原創合成資料研究「ScaLAPACK：區塊循環索引與矩陣所有權驗證」，從物理或資料契約推導計算，並以反例驗證。完成：交付兩組所有權圖、九十六元素計數、邊緣區塊與 gather 比對。","differenceEn":"Investigate ScaLAPACK: block-cyclic indexing and matrix ownership using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver both ownership maps, ninety-six-entry coverage checks, partial-edge-block records and gather comparisons with indexing and process-order conventions preserved.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["分別計兩個節點的四次方與權重，說明規則只保證至三次，因此失敗不是浮點微小誤差。","i=6、j=10 除區塊二取 floor，得到區塊 (3,5)，再循環到程序 (1,2)。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Evaluate the fourth power at both nodes and apply their weights. Explain that the rule guarantees only degree-three exactness, so the observed discrepancy is a structural underintegration error rather than a tiny floating-point artifact.","Divide i=6 and j=10 by block size two and take floors, obtaining block coordinates (3,5). Cycle these across the process grid, retaining intermediate coordinates so each ownership transformation is auditable.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v27-case-1ef30f43c519cf82","url":"https://dealii.org/9.6.0/doxygen/deal.II/step_6.html","title":"deal.II adaptive finite elements tutorial step-6","titleEn":"deal.II adaptive finite elements tutorial step-6","publisher":"deal.II","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v27-case-5b709369d980ec78","url":"https://www.netlib.org/scalapack/slug/node75.html","title":"ScaLAPACK two-dimensional block cyclic distribution","titleEn":"ScaLAPACK two-dimensional block cyclic distribution","publisher":"ScaLAPACK / Netlib","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
